/// App commands the UI may call. Each one gets generated `allow-<command>` / `deny-<command>`
/// permissions (in `permissions/autogenerated/`, git-ignored); `capabilities/default.json` grants
/// exactly the ones the main window uses. Keep this list in sync with `generate_handler!` in
/// `src/lib.rs`: a command missing here cannot be granted, so the UI's call is rejected.
const COMMANDS: &[&str] = &[
    "app_info",
    "demo_arrow_page",
    "list_profiles",
    "save_profile",
    "delete_profile",
    "test_connection",
    "open_connection",
    "cancel_request",
    "close_connection",
    "list_open_connections",
    // M2 workbench (src/workbench.rs).
    "tree_children",
    "object_load",
    "query_run",
    "query_page",
    "query_cancel",
    "query_close",
    "query_close_editor",
    "statement_at",
    "history_list",
    "history_delete",
    "history_clear",
    "history_get_settings",
    "history_set_settings",
    // M3 table data and editing (src/data.rs).
    "table_data_open",
    "edit_begin",
    "edit_apply",
    "row_get_form",
    // M3 table designer (src/designer.rs).
    "designer_load",
    "designer_preview",
    "designer_apply",
    "capabilities_get",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("failed to run the Tauri build script");
}
